var d1='<div class="letter doc" contenteditable="true">'+hdr("Section 37(2) agreement",an)+'<h2>AGREEMENT IN TERMS OF SECTION 37(2) OF THE OCCUPATIONAL HEALTH AND SAFETY ACT 85 OF 1993</h2><p>Entered into between</p><p>'+ub(co)+' (the principal contractor, called "the employer" in this agreement)</p><p>and</p><p>'+ub(cn)+', registration number '+ub(cr)+' (the contractor, called "the mandatary" in this agreement), represented by '+ub(rp)+' in the capacity of '+ub(rq)+'.</p>'
