sec("Objectives and targets",tbl(["Objective","Target","Measure","Frequency"],[["Fatalities and serious injuries","0","Incident statistics","Continuous"],["Risk assessment before each task","100%","Supervisor verification","Each task"],["Workers competent before the task","100%","Training audit","Before work and monthly"],["Equipment pre-use inspections","100%","Inspection registers","Each use"],["Incident reporting","100% reported promptly","Incident records","As required"],["Planned inspections completed","100%","Inspection schedule","Weekly and monthly"],["Environmental releases","0 uncontrolled","Spill and waste inspections","Monthly"]]));
sec("Incidents and accident investigations",ul(["Report all incidents, near misses and unsafe conditions to the supervisor immediately.","Preserve the scene where safe and cooperate with investigations.","Report serious incidents to management and the client at once, and give the legal notifications required under the OHS Act.","Assign corrective actions, track them to closure and share lessons at toolbox talks."]));
sec("Communication, SHE meetings and toolbox talks",tbl(["Communication","Frequency","Responsible"],[["Site induction","Before site work","SHE / supervisor"],["Pre-task briefing","Before each task or shift","Supervisor"],["Toolbox talk","Daily when work is active","Supervisor"],["SHE meeting","Monthly or as the client requires","Project manager / SHE"]])+"<p>All workers have stop-work authority. Communication shall be in a language the workforce understands.</p>");
sec("Subcontractor management",$("ctc").checked?"<p><b>A contractor will be used on this work:</b></p><p>"+ctxCon()+"</p>"+ul(["The contractor is appointed in writing and is given the relevant parts of the health and safety specification.","Before appointment the contractor’s competence and compensation registration are checked, and a Section 37(2) agreement is in place.","The contractor provides a documented health and safety plan based on this plan, and it is approved before work starts (Construction Regulation 7).","The contractor’s workers complete the site induction, hold valid medical certificates of fitness and are covered by the risk assessments.","The contractor keeps a health and safety file on site, provides its own legal appointments, training and equipment inspection records, and is added to the contractor list.","This plan and the contractor’s work are monitored by inspections and audits."]):"<p>No contractor will be used on this work. If that changes, no contractor starts before the client’s approval, a competent contractor is appointed in writing with a Section 37(2) agreement, and this plan is updated.</p>");
sec("Hazard identification, risk assessment and risk mitigation plan","<p>Risk is assessed on a 5×5 matrix: Risk = Likelihood × Severity. Bands: 1–4 Low, 5–9 Medium, 10–16 High, 17–25 Critical. Raw risk is assessed before controls and residual risk after controls. Risk assessment: <b>"+hn+"</b> ("+H.length+" entries). Task specific risk assessments are required for non-routine and high-risk tasks. Critical residual risk is not accepted: work stops until the risk is reduced.</p>");
sec("Medical surveillance and fitness",ul(["Workers shall be certified fit for their work before they are assigned.","Workers doing high-risk work (heights, confined spaces, lifting, plant operation, hazardous chemicals) need a medical fitness certificate suited to that work.","Medical records are confidential."]));
sec("Health and safety training and competence",ul(["Every worker completes a site induction before starting.","Competence is verified before a task is assigned: certificates, licences and appointments are on file.","Training needed for this scope: "+esc((sel.length?sel.join("; "):"as per the risk assessment"))+" – including first aid, fire fighting and toolbox talks."]));
sec("Internal and external audits and inspections",ul(["Planned inspections use the following registers: "+R.map(esc).join("; ")+".","The SHE officer audits this plan and the site at least monthly. Findings are tracked to closure.","Client and statutory audits are supported and their findings closed out."]));
sec("PPE arrangements and PPE matrix",tbl(["Work type","Minimum PPE"],sel.map(function(k){return[esc(k),esc(P[k]||PG)]}).concat([["General",esc(PG)]]))+"<p>PPE is issued free, recorded in the PPE register and replaced when damaged. Client site and permit requirements apply in addition.</p>");
sec("Site establishment, safety signage and boards",ul(["Provide a notice board with the SHE policy, emergency numbers, appointments and the notification where required.","Erect mandatory, warning and prohibition signs at hazard areas and barricade excavations, edges and lifting zones.","Keep access routes, emergency routes and assembly points clear."]));
sec("Resource utilisation",tbl(["Name","ID number","Role"],tm.length?tm.map(function(m){return[esc(m.n),esc(m.i),esc(m.r)]}):[["Not captured","",""]]));
sec("Welfare facilities",ul(["Provide drinking water, toilets, hand washing and a place to eat and change, as the Construction Regulations and the client require.","Keep facilities clean and stocked."]));
sec("Security, pedestrian and traffic control",ul(["Only inducted and authorised persons enter the site.","Separate pedestrians from vehicles and plant. Use marshals where needed.","Obey site speed limits and designated routes."]));
sec("Measurement and review of SHE performance",ul(["Track incidents, near misses, inspections done, training done and actions closed.","Review performance monthly and after any serious incident.","Review this plan whenever scope, conditions, methods or the law change, and at the review date."]));
sec("General inspections and maintenance of equipment","<p>All equipment is inspected before use and kept in good order. Defective equipment is tagged out and removed. Registers: "+R.map(esc).join("; ")+".</p>");
sec("Exit criteria, demobilisation and end of contract",ul(["Return permits and keys, and hand the area over clean and safe.","Remove waste, chemicals, temporary works and equipment.","Close out outstanding actions and hand over the SHE file."]));
sec("Emergency preparedness",ul(["Display emergency numbers, the muster point and the evacuation route.","Keep a trained first aider, a stocked first aid box and fire extinguishers on site.","Know the client’s emergency alarms and procedures.","Drill the emergency plan, including rescue where work at height, confined space or excavation applies."]));
sec("Smoking arrangements","<p>Smoking is only allowed in designated areas approved by the client and the supervisor. No smoking near flammables, fuels or hot work.</p>");
sec("Non-conformance management and deviations",ul(["Record any non-conformance or deviation from this plan.","Do not continue a task that deviates from its risk assessment or procedure; stop and reassess.","Assign and track corrective actions to closure."]));
sec("Environmental management",ul(["Control waste, dust, noise and spills. Keep spill kits where fuels or chemicals are used.","Separate and dispose of waste lawfully.","Report any spill or environmental release at once."]));
var c=[[["Working at heights","Scaffolding","Roofing and sheeting"],"Work at height",["No person works at height without a fall protection plan, trained and fit workers, inspected harnesses and anchor points, and a rescue plan.","Use edge protection and scaffolds before personal fall arrest where practicable.","Stop work in wind, rain or poor light."]],[["Lifting and cranes"],"Lifting and rigging",["Lift only to an approved lift plan with certified tackle and a competent operator, rigger and signaller.","Establish an exclusion zone and never stand under a load.","Inspect tackle before each use."]],[["Hazardous chemicals and fuels","Painting and coating"],"Chemicals and hazardous substances",["Keep the SDS on site and label all containers.","Store chemicals in a ventilated, bunded area, segregated by compatibility.","Use the PPE the SDS requires and keep spill kits ready."]],[["Hot work (welding and cutting)","Grinding and abrasive cutting"],"Hot work",["Use a hot work permit, clear combustibles, post a fire watch and keep extinguishers at hand.","Keep gas cylinders upright, secured and fitted with flashback arrestors."]],[["Excavation"],"Excavation",["Use a permit to dig and locate services first.","Shore or batter the sides and keep spoil and plant back from the edge.","Inspect excavations daily and barricade them."]],[["Confined space"],"Confined space entry",["Enter only under a permit after isolation and gas testing.","Keep a trained standby person and a rescue plan ready."]],[["Electrical work","Mechanical maintenance and repair"],"Isolation and lock out",["Work only on equipment that is isolated, locked out and proved safe.","Do not bypass or remove another person’s lock."]],[["Mobile plant and vehicles"],"Mobile plant and traffic",["Use only licensed, authorised operators and inspect plant before use.","Use banksmen and keep pedestrians separate."]]];
